{
  "assessment": "The source provides a quantitative relation between the Lyapunov exponent and Reynolds number in turbulence, with a fitted exponent alpha = 0.59 ± 0.04, supported by DNS and shell model data. The selected cluster is the scaling lambda ~ Re^alpha, with controls Re (DNS and GOY ranges) and readouts lambda, lambda_DNS, lambda_GOY, gamma3_std, and -<gamma3>. The source reports two regimes: DNS (Re 50-1400) and GOY shell model (Re 8.7e6-2.6e8), which can be treated as separate claims sharing the same mechanism. The extraction is case_authoring_ready because there is at least one numeric control (Re), numeric readouts (lambda etc.), a quantitative mechanism (lambda ~ Re^alpha), and an explicit domain.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Aikya Banerjee, Intermittent Fluctuations Determine the Nature of Chaos in Turbulence, Physical Review Letters (2026), DOI:10.1103/1dj2-zw28",
    "journal_doi": "10.1103/1dj2-zw28",
    "arxiv_versioned_id": "2505.09538v1"
  },
  "paper_scope": "The paper studies the Reynolds number dependence of the largest Lyapunov exponent in fully developed turbulence, using decorrelators from the Navier-Stokes equation and the GOY shell model. It derives a scaling lambda ~ Re^alpha with alpha = 0.59 ± 0.04, and connects this to intermittent fluctuations in the compressional eigenvalue of the strain-rate tensor.",
  "mechanisms": [
    {
      "mechanism_id": "lyapunov_scaling",
      "statement": "The Lyapunov exponent lambda scales as a power law with Reynolds number: lambda ~ Re^alpha, with alpha = 0.59 ± 0.04. This scaling is universal across DNS and GOY shell model, and is dominated by the standard deviation of the compressional eigenvalue gamma_3^std ~ Re^alpha, while the mean -<gamma_3> ~ sqrt(Re).",
      "equations": [
        "lambda = lambda_DNS = lambda_GOY ~ Re^alpha, alpha = 0.59 ± 0.04",
        "lambda_S ~ <gamma_3> + gamma_3^std",
        "gamma_3^std ~ Re^alpha",
        "-<gamma_3> ~ sqrt(Re)"
      ],
      "variable_names": ["lambda", "lambda_DNS", "lambda_GOY", "Re", "alpha", "gamma_3", "gamma_3^std", "<gamma_3>", "lambda_S"],
      "parameters": [
        {
          "name": "alpha_lyapunov",
          "value": 0.59,
          "uncertainty": "± 0.04 (convention source_unspecified)",
          "unit": "dimensionless",
          "role": "power-law exponent in lambda ~ Re^alpha",
          "anchors": [
            {"line_start": 46, "line_end": 47, "support": "Abstract states alpha = 0.59 ± 0.04."},
            {"line_start": 388, "line_end": 391, "support": "Universal scaling lambda_DNS = lambda_GOY = lambda ~ Re^alpha with alpha = 0.59 ± 0.04, holding for nearly 7 decades in Re."},
            {"line_start": 635, "line_end": 635, "support": "lambda = lambda_DNS ~ lambda_S ~ Re^alpha with alpha = 0.59 ± 0.04."}
          ]
        },
        {
          "name": "gamma3_std_exponent",
          "value": 0.59,
          "uncertainty": "± 0.04 (convention source_unspecified)",
          "unit": "dimensionless",
          "role": "power-law exponent in gamma_3^std ~ Re^alpha",
          "anchors": [
            {"line_start": 397, "line_end": 398, "support": "gamma_3^std ~ Re^alpha and lambda = lambda_DNS = gamma_3^std ~ Re^0.59."},
            {"line_start": 632, "line_end": 634, "support": "<Delta Theta^2> proportional to gamma_3^std ~ Re^0.59."}
          ]
        },
        {
          "name": "mean_gamma3_exponent",
          "value": 0.5,
          "uncertainty": "None reported",
          "unit": "dimensionless",
          "role": "power-law exponent in -<gamma_3> ~ sqrt(Re)",
          "anchors": [
            {"line_start": 399, "line_end": 400, "support": "Mean eigenvalue -<gamma_3> ~ sqrt(Re)."},
            {"line_start": 629, "line_end": 629, "support": "<Delta Theta> proportional to <gamma_3> ~ sqrt(Re)."}
          ]
        }
      ],
      "anchors": [
        {"line_start": 46, "line_end": 48, "support": "Abstract: alpha = 0.59 ± 0.04 and departure from Kolmogorov mean field lambda ~ sqrt(Re)."},
        {"line_start": 388, "line_end": 391, "support": "Universal scaling lambda_DNS = lambda_GOY = lambda ~ Re^alpha with alpha = 0.59 ± 0.04, nearly 7 decades."},
        {"line_start": 393, "line_end": 400, "support": "Theory connects lambda_S ~ <gamma_3> + gamma_3^std; gamma_3^std ~ Re^alpha and -<gamma_3> ~ sqrt(Re)."},
        {"line_start": 635, "line_end": 635, "support": "lambda = lambda_DNS ~ lambda_S ~ Re^alpha with alpha = 0.59 ± 0.04."}
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "dns_setup",
      "statement": "DNS of 3D incompressible Navier-Stokes on a 2π triply-periodic box with N=256 or 512 collocation points, pseudospectral method, second-order Adams-Bashforth time stepping, constant energy injection at wavenumbers 1 ≤ k_force ≤ 2, initial perturbation Gaussian with epsilon_0 = 1e-5, sigma_0 = 4 dx, localized at center.",
      "anchors": [
        {"line_start": 460, "line_end": 470, "support": "DNS details: periodic box L=2π, N=256/512, viscosity range, time steps."},
        {"line_start": 472, "line_end": 481, "support": "Initial spectrum, forcing, and Gaussian perturbation parameters."}
      ]
    },
    {
      "condition_id": "goy_setup",
      "statement": "GOY shell model with N=22 shells, k_n = k_0 2^n, k_0 = 1, constant forcing f = 0.1 on shell n=2, second-order Runge-Kutta with time step 2e-5, perturbation epsilon_0 = 0.001 on shell n_p = 16.",
      "anchors": [
        {"line_start": 499, "line_end": 510, "support": "GOY model parameters: N=22, viscosity range, Re definition, time step, forcing."},
        {"line_start": 515, "line_end": 523, "support": "Perturbation epsilon_0 = 0.001 and n_p = 16."}
      ]
    }
  ],
  "controls": [
    {
      "name": "Re_DNS",
      "definition": "Reynolds number in the DNS simulations, varied by changing kinematic viscosity.",
      "unit": "dimensionless",
      "domain_kind": "continuous_interval",
      "minimum": 50,
      "maximum": 1400,
      "allowed_values": [],
      "domain_statement": "Reynolds numbers 50 ≤ Re ≤ 1400 obtained by varying viscosity 1e-3 ≤ ν ≤ 32e-3.",
      "anchors": [
        {"line_start": 467, "line_end": 467, "support": "Vary viscosity to obtain Reynolds numbers 50 ≤ Re ≤ 1400."}
      ]
    },
    {
      "name": "Re_GOY",
      "definition": "Reynolds number in the GOY shell model, defined as Re = |u_rms|/(k_0 ν).",
      "unit": "dimensionless",
      "domain_kind": "continuous_interval",
      "minimum": 8700000,
      "maximum": 260000000,
      "allowed_values": [],
      "domain_statement": "Reynolds numbers in range 8.7e6 ≤ Re ≤ 2.6e8, with viscosity varying 2e-7 ≤ ν ≤ 64e-7.",
      "anchors": [
        {"line_start": 503, "line_end": 507, "support": "Viscosity range yields Re range 8.7e6 to 2.6e8; Re defined as |u_rms|/k_0 ν."}
      ]
    }
  ],
  "readouts": [
    {
      "name": "lambda_DNS",
      "definition": "Largest Lyapunov exponent extracted from the exponential growth phase of the spatially averaged decorrelator Φ(t) in DNS.",
      "unit": "1/time (arbitrary units)",
      "statistic": "Linear fit to the exponential growth phase of Φ(t); errorbars from fit errors.",
      "uncertainty": "Errorbars smaller than symbol sizes; convention not specified.",
      "resolution": null,
      "anchors": [
        {"line_start": 289, "line_end": 295, "support": "Φ from DNS shows exponential regime from which λ_DNS is extracted."},
        {"line_start": 371, "line_end": 376, "support": "Lyapunov exponents estimated from linear fit in exponential-growth phase; errors from fits."}
      ]
    },
    {
      "name": "lambda_GOY",
      "definition": "Lyapunov exponent from the integrated GOY shell model decorrelator Φ^GOY = sum_n φ_n, extracted from exponential growth phase.",
      "unit": "1/time (arbitrary units)",
      "statistic": "Linear fit to exponential growth phase of Φ^GOY; errorbars from fit errors.",
      "uncertainty": "Errorbars smaller than symbol sizes; convention not specified.",
      "resolution": null,
      "anchors": [
        {"line_start": 356, "line_end": 361, "support": "λ^GOY from integrated decorrelator Φ^GOY showing exponential growth."},
        {"line_start": 371, "line_end": 376, "support": "Lyapunov exponents estimated from linear fit; errors from fits."}
      ]
    },
    {
      "name": "gamma3_std",
      "definition": "Standard deviation of the compressional eigenvalue γ_3 of the strain-rate tensor, measured from DNS.",
      "unit": "1/time (arbitrary units)",
      "statistic": "Standard deviation of γ_3 distribution; errorbars extracted similarly to λ_DNS.",
      "uncertainty": "Errorbars of same order as λ_DNS; convention not specified.",
      "resolution": null,
      "anchors": [
        {"line_start": 377, "line_end": 379, "support": "Errorbars for γ_3 extracted likewise and of same order as λ_DNS."},
        {"line_start": 397, "line_end": 398, "support": "Plot of γ_3^std from DNS shows near perfect agreement with Lyapunov exponent."}
      ]
    },
    {
      "name": "mean_gamma3_abs",
      "definition": "Absolute value of the mean compressional eigenvalue -<γ_3> of the strain-rate tensor, measured from DNS.",
      "unit": "1/time (arbitrary units)",
      "statistic": "Mean of γ_3 distribution; errorbars not explicitly reported.",
      "uncertainty": "Not reported.",
      "resolution": null,
      "anchors": [
        {"line_start": 399, "line_end": 400, "support": "Mean eigenvalue -<γ_3> ~ sqrt(Re) shown in Fig. 4."}
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "lambda_DNS_scaling",
      "statement": "The Lyapunov exponent from DNS scales as λ_DNS ~ Re^α with α = 0.59 ± 0.04, consistent with the universal scaling.",
      "quantitative_form": "λ_DNS = C_DNS * Re^0.59",
      "oracle_outputs": {
        "lambda_DNS": {
          "op": "multiply",
          "args": [
            {"param": "prefactor_DNS"},
            {"op": "power", "args": [{"var": "Re_DNS"}, {"param": "alpha_lyapunov"}]}
          ]
        }
      },
      "mechanism_ids": ["lyapunov_scaling"],
      "control_names": ["Re_DNS"],
      "control_domains": [
        {
          "control_name": "Re_DNS",
